561	// FetchBlobsByHash fetches specific blob objects from the remote by their SHA-1 hashes.
562	// Uses "git fetch <target> <hash>" which goes through normal credential helpers,
563	// unlike fetch-pack which bypasses them. Requires the server to support
564	// uploadpack.allowReachableSHA1InWant (GitHub, GitLab, Bitbucket all do).
565	//
566	// The fetch target is resolved via resolveCheckpointFetchTarget, which defers to
567	// checkpoint/remote.FetchURL for the effective remote URL when available.
568	//
569	// If fetching by hash fails, falls back to a full metadata branch fetch.
570	func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
571		if len(hashes) == 0 {
572			return nil
573		}
574	
575		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
576		defer cancel()
577	
578		fetchTarget := resolveCheckpointFetchTarget(ctx)
579	
580		hashStrs := make([]string, len(hashes))
581		for i, h := range hashes {
582			hashStrs[i] = h.String()
583		}
584	
585		if fetchErr := remote.FetchBlobs(ctx, fetchTarget, hashStrs); fetchErr != nil {
586			logging.Debug(ctx, "fetch-by-hash failed, falling back to full metadata fetch",
587				slog.Int("blob_count", len(hashes)),
588				slog.String("fetch_target", fetchTarget),
589				slog.String("error", fetchErr.Error()),
590			)
591			// Fallback: try checkpoint remote first (if configured), then origin
592			if cpErr := FetchMetadataFromCheckpointRemote(ctx); cpErr != nil {
593				if fallbackErr := FetchMetadataBranch(ctx); fallbackErr != nil {
594					return fmt.Errorf("fetch-by-hash failed: %w; fallback fetch also failed: %w",
595						fetchErr, fallbackErr)
596				}
597			}
598		}
599	
600		return nil
601	}
