75	// FetchBlobs fetches specific objects (typically blobs) by hash from a remote.
76	// Uses `git fetch-pack` rather than `git fetch` because the high-level
77	// porcelain enforces partial-clone integrity checks that reject blob-only
78	// responses with "did not send all necessary objects". Plumbing skips those
79	// checks — it just downloads the requested objects into .git/objects/pack
80	// and exits — which is exactly what we want when grabbing individual blobs
81	// by SHA. Works against GitHub for any reachable object, including blobs.
82	//
83	// The remote should be a URL (not a remote name) to avoid persisting promisor
84	// settings onto the named remote. Use FetchURL to obtain the URL.
85	func FetchBlobs(ctx context.Context, remote string, hashes []string) error {
86		args := []string{"fetch-pack", remote}
87		args = append(args, hashes...)
88	
89		cmd := newCommand(ctx, args...)
90		disableTerminalPrompt(cmd)
91		output, err := cmd.CombinedOutput()
92		if err != nil {
93			redactedURL := RedactURL(remote)
94			msg := strings.TrimSpace(strings.ReplaceAll(string(output), remote, redactedURL))
95			if msg != "" {
96				return fmt.Errorf("git fetch-pack from %s: %s: %w", redactedURL, msg, err)
97			}
98			return fmt.Errorf("git fetch-pack from %s: %w", redactedURL, err)
99		}
100		return nil
101	}
