103	// CatFilesOptions configures a git cat-file --batch read.
104	type CatFilesOptions struct {
105		Specs     []string // one or more object names or revspecs
106		Dir       string   // working directory (empty = CWD)
107		ExtraArgs []string // additional flags before --batch
108	}
109	
110	// CatFileResult is the result of reading one cat-file batch spec.
111	type CatFileResult struct {
112		Content []byte
113		Missing bool
114		Err     error
115	}
116	
117	// CatFiles reads specs through git cat-file --batch.
118	func CatFiles(ctx context.Context, opts CatFilesOptions) map[string]CatFileResult {
119		specs := uniqueStrings(opts.Specs)
120		results := make(map[string]CatFileResult, len(specs))
121		if len(specs) == 0 {
122			return results
123		}
124	
125		args := []string{"cat-file"}
126		args = append(args, opts.ExtraArgs...)
127		args = append(args, "--batch")
128		cmd := newCommand(ctx, args...)
129		if opts.Dir != "" {
130			cmd.Dir = opts.Dir
131		}
132		cmd.Stdin = strings.NewReader(strings.Join(specs, "\n") + "\n")
133		disableTerminalPrompt(cmd)
134		var stderr bytes.Buffer
135		cmd.Stderr = &stderr
136	
137		output, err := cmd.Output()
138		if err != nil {
139			wrapped := catFilesError(err, stderr.String())
140			for _, spec := range specs {
141				results[spec] = CatFileResult{Err: wrapped}
142			}
143			return results
144		}
145	
146		reader := bufio.NewReader(bytes.NewReader(output))
147		for i, spec := range specs {
148			result, parseErr := parseBlobBatchEntry(reader)
149			if parseErr != nil {
150				for _, s := range specs[i:] {
151					results[s] = CatFileResult{Err: parseErr}
152				}
153				break
154			}
155			results[spec] = result
156		}
157		return results
158	}
159	
160	func parseBlobBatchEntry(reader *bufio.Reader) (CatFileResult, error) {
161		header, err := reader.ReadString('\n')
162		if err != nil {
163			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
164		}
165		header = strings.TrimSuffix(header, "\n")
166	
167		fields := strings.Fields(header)
168		if len(fields) == 2 && fields[1] == "missing" {
169			return CatFileResult{Missing: true}, nil
170		}
171		if len(fields) != 3 {
172			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: unexpected header %q", header)
173		}
