314	// ChunkTranscript splits a Gemini JSON transcript by distributing messages across chunks.
315	// Gemini uses JSON format with a {"messages": [...]} structure, so chunking splits
316	// the messages array while preserving the JSON structure in each chunk.
317	func (g *GeminiCLIAgent) ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error) {
318		var transcript GeminiTranscript
319		if err := json.Unmarshal(content, &transcript); err != nil {
320			// Fall back to JSONL chunking if not valid Gemini JSON
321			chunks, chunkErr := agent.ChunkJSONL(content, maxSize)
322			if chunkErr != nil {
323				return nil, fmt.Errorf("failed to chunk as JSONL: %w", chunkErr)
324			}
325			return chunks, nil
326		}
327	
328		if len(transcript.Messages) == 0 {
329			return [][]byte{content}, nil
330		}
331	
332		var chunks [][]byte
333		var currentMessages []GeminiMessage
334		currentSize := len(`{"messages":[]}`) // Base JSON structure size
335	
336		for i, msg := range transcript.Messages {
337			// Marshal message to get its size
338			msgBytes, err := json.Marshal(msg)
339			if err != nil {
340				logging.Warn(ctx, "failed to marshal Gemini message during chunking",
341					slog.Int("message_index", i),
342					slog.String("error", err.Error()),
343				)
344				continue
345			}
346			msgSize := len(msgBytes) + 1 // +1 for comma separator
347	
348			if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
349				// Save current chunk
350				chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
351				if err != nil {
352					return nil, fmt.Errorf("failed to marshal chunk: %w", err)
353				}
354				chunks = append(chunks, chunkData)
355	
356				// Start new chunk
357				currentMessages = nil
358				currentSize = len(`{"messages":[]}`)
359			}
360	
361			currentMessages = append(currentMessages, msg)
362			currentSize += msgSize
363		}
364	
365		// Add the last chunk
366		if len(currentMessages) > 0 {
367			chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
368			if err != nil {
369				return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
370			}
371			chunks = append(chunks, chunkData)
372		}
373	
374		// Ensure we created at least one chunk (could be empty if all messages failed to marshal)
375		if len(chunks) == 0 {
376			return nil, errors.New("failed to create any chunks: all messages failed to marshal")
377		}
378	
379		return chunks, nil
380	}
