271	// GetTranscriptPosition returns the current line count of a Claude Code transcript.
272	// Claude Code uses JSONL format, so position is the number of lines.
273	// This is a lightweight operation that only counts lines without parsing JSON.
274	// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
275	// Returns 0 if the file doesn't exist or is empty.
276	func (c *ClaudeCodeAgent) GetTranscriptPosition(path string) (int, error) {
277		if path == "" {
278			return 0, nil
279		}
280	
281		file, err := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
282		if err != nil {
283			if os.IsNotExist(err) {
284				return 0, nil
285			}
286			return 0, fmt.Errorf("failed to open transcript file: %w", err)
287		}
288		defer file.Close()
289	
290		reader := bufio.NewReader(file)
291		lineCount := 0
292	
293		for {
294			line, err := reader.ReadBytes('\n')
295			if err != nil {
296				if err == io.EOF {
297					if len(line) > 0 {
298						lineCount++ // Count final line without trailing newline
299					}
300					break
301				}
302				return 0, fmt.Errorf("failed to read transcript: %w", err)
303			}
304			lineCount++
305		}
306	
307		return lineCount, nil
308	}
