310	// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
311	// For Claude Code (JSONL format), offset is the starting line number.
312	// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
313	// Returns:
314	//   - files: list of file paths modified by Claude (from Write/Edit tools)
315	//   - currentPosition: total number of lines in the file
316	//   - error: any error encountered during reading
317	func (c *ClaudeCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
318		if path == "" {
319			return nil, 0, nil
320		}
321	
322		file, openErr := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
323		if openErr != nil {
324			return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
325		}
326		defer file.Close()
327	
328		reader := bufio.NewReader(file)
329		var lines []TranscriptLine
330		lineNum := 0
331	
332		for {
333			lineData, readErr := reader.ReadBytes('\n')
334			if readErr != nil && readErr != io.EOF {
335				return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
336			}
337	
338			if len(lineData) > 0 {
339				lineNum++
340				if lineNum > startOffset {
341					var line TranscriptLine
342					if parseErr := json.Unmarshal(lineData, &line); parseErr == nil {
343						lines = append(lines, line)
344					}
345					// Skip malformed lines silently
346				}
347			}
348	
349			if readErr == io.EOF {
350				break
351			}
352		}
353	
354		return ExtractModifiedFiles(lines), lineNum, nil
355	}
