70	// ChunkTranscript splits an OpenCode export JSON transcript by distributing messages across chunks.
71	// OpenCode uses JSON format with {"info": {...}, "messages": [...]} structure.
72	func (a *OpenCodeAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
73		var session ExportSession
74		if err := json.Unmarshal(content, &session); err != nil {
75			return nil, fmt.Errorf("failed to parse export session for chunking: %w", err)
76		}
77	
78		if len(session.Messages) == 0 {
79			return [][]byte{content}, nil
80		}
81	
82		// Marshal info to calculate accurate base size
83		infoBytes, err := json.Marshal(session.Info)
84		if err != nil {
85			return nil, fmt.Errorf("failed to marshal session info for chunking: %w", err)
86		}
87		// Base JSON structure size: {"info":<info>,"messages":[ ... ]}
88		baseSize := len(`{"info":`) + len(infoBytes) + len(`,"messages":[]}`)
89	
90		var chunks [][]byte
91		var currentMessages []ExportMessage
92		currentSize := baseSize
93	
94		for _, msg := range session.Messages {
95			// Marshal message to get its size
96			msgBytes, err := json.Marshal(msg)
97			if err != nil {
98				return nil, fmt.Errorf("failed to marshal message for chunking: %w", err)
99			}
100			msgSize := len(msgBytes) + 1 // +1 for comma separator
101	
102			if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
103				// Save current chunk
104				chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
105				if err != nil {
106					return nil, fmt.Errorf("failed to marshal chunk: %w", err)
107				}
108				chunks = append(chunks, chunkData)
109	
110				// Start new chunk
111				currentMessages = nil
112				currentSize = baseSize
113			}
114	
115			currentMessages = append(currentMessages, msg)
116			currentSize += msgSize
117		}
118	
119		// Add the last chunk
120		if len(currentMessages) > 0 {
121			chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
122			if err != nil {
123				return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
124			}
125			chunks = append(chunks, chunkData)
126		}
127	
128		if len(chunks) == 0 {
129			return nil, errors.New("failed to create any chunks")
130		}
131	
132		return chunks, nil
133	}
