135	// ReassembleTranscript merges OpenCode export JSON chunks by combining their message arrays.
136	func (a *OpenCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
137		if len(chunks) == 0 {
138			return nil, errors.New("no chunks to reassemble")
139		}
140	
141		var allMessages []ExportMessage
142		var sessionInfo SessionInfo
143	
144		for i, chunk := range chunks {
145			var session ExportSession
146			if err := json.Unmarshal(chunk, &session); err != nil {
147				return nil, fmt.Errorf("failed to unmarshal chunk %d: %w", i, err)
148			}
149			if i == 0 {
150				sessionInfo = session.Info // Preserve session info from first chunk
151			}
152			allMessages = append(allMessages, session.Messages...)
153		}
154	
155		result, err := json.Marshal(ExportSession{Info: sessionInfo, Messages: allMessages})
156		if err != nil {
157			return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
158		}
159		return result, nil
160	}
