// GetSessionDir returns the directory where Entire stores OpenCode session transcripts.
// Transcripts are ephemeral handoff files between the TS plugin and the Go hook handler.
// Once checkpointed, the data lives on git refs and the file is disposable.
// Stored under <repoPath>/.entire/tmp/ to match where fetchAndCacheExport writes
// the live transcript (lifecycle.go:sessionTranscriptPath). Keeping both paths
// aligned removes a class of read-vs-write mismatches in rewind/resume and avoids
// squatting on a shared os.TempDir() location where other users on a multi-user
// system could read restored transcripts. Also worktree-safe: each worktree has
// its own .entire/ directory.
func (a *OpenCodeAgent) GetSessionDir(repoPath string) (string, error) {
	// Check for test environment override
	if override := os.Getenv("ENTIRE_TEST_OPENCODE_PROJECT_DIR"); override != "" {
		return override, nil
	}

	return filepath.Join(repoPath, paths.EntireTmpDir), nil
}

