144	// pathHasDirPrefix reports whether path is contained within dir (or equals it).
145	// Adds a trailing separator before prefix-matching so /a/bc doesn't match /a/b.
146	//
147	// On Windows, comparison is case-insensitive: NTFS/ReFS treat paths as
148	// case-insensitive, and filepath.Abs preserves whatever casing the input had,
149	// so a transcript path like `C:\Users\Bob\.cursor\...` and a session dir like
150	// `c:\users\bob\.cursor\...` refer to the same location but would not match
151	// under a byte-wise comparison.
152	func pathHasDirPrefix(path, dir string) bool {
153		if runtime.GOOS == "windows" {
154			path = strings.ToLower(path)
155			dir = strings.ToLower(dir)
156		}
157		if path == dir {
158			return true
159		}
160		if !strings.HasSuffix(dir, string(filepath.Separator)) {
161			dir += string(filepath.Separator)
162		}
163		return strings.HasPrefix(path, dir)
164	}
